import{_ as c,r as e,o as i,c as u,e as p,a as n,s as t,d as s}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"组件 - October CMS - 3.x","titleTemplate":false,"description":"可附加到任何页面、部件或布局的可配置控制器。","frontmatter":{"subtitle":"可附加到任何页面、部件或布局的可配置控制器。"},"headers":[{"level":2,"title":"介绍","slug":"介绍","link":"#介绍","children":[]},{"level":2,"title":"组件别名","slug":"组件别名","link":"#组件别名","children":[]},{"level":2,"title":"使用外部属性值","slug":"使用外部属性值","link":"#使用外部属性值","children":[]},{"level":2,"title":"向组件传递变量","slug":"向组件传递变量","link":"#向组件传递变量","children":[]},{"level":2,"title":"自定义默认标记","slug":"自定义默认标记","link":"#自定义默认标记","children":[{"level":3,"title":"将默认标记移动到部件","slug":"将默认标记移动到部件","link":"#将默认标记移动到部件","children":[]},{"level":3,"title":"覆盖组件部件","slug":"覆盖组件部件","link":"#覆盖组件部件","children":[]}]},{"level":2,"title":"\\"View Bag\\" 组件","slug":"view-bag-组件","link":"#view-bag-组件","children":[{"level":3,"title":"AJAX 处理器和部件","slug":"ajax-处理器和部件","link":"#ajax-处理器和部件","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}]}],"relativePath":"3.x/zh-cn/cms/themes/components.md","filePath":"3.x/zh-cn/cms/themes/components.md"}'),r={name:"3.x/zh-cn/cms/themes/components.md"};function g(k,a,d,m,v,h){const o=e("pre-heading"),l=e("post-heading");return i(),u("div",null,[p(o),a[0]||(a[0]=n("h1",null,"组件",-1)),p(l),a[1]||(a[1]=t(`<p>组件是使用 October CMS 构建可扩展的现代化解决方案的关键功能。每个组件实现了一些扩展您网站的功能。组件可以在页面上输出 HTML 标记，但这不是必需的——组件的其他重要功能包括<a href="./../ajax/introduction.html">处理 AJAX 请求</a>、处理表单回传以及处理页面执行生命周期，允许向页面注入变量或实现网站安全性。</p><p>本文介绍了组件的基础知识，不涉及如何<a href="./../ajax/handlers.html">将组件与 AJAX 结合使用</a>、作为插件的一部分<a href="./../../extend/cms-components.html">开发组件</a>，或 October CMS <a href="./../components/section.html">内置的组件</a>。</p><h2 id="介绍"><a href="#介绍" class="header-anchor">#</a> 介绍</h2><p>组件可以在管理面板的编辑器中找到。您可以通过点击任何打开文档上的组件工具栏按钮，将组件添加到页面、部件和布局中。如果您使用文本编辑器，可以通过将组件名称添加到模板文件的配置部分来将组件附加到页面或布局。下面的示例演示了如何将一个演示待办事项组件添加到页面。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Components demonstration</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/components</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- HTML Content Here --&gt;</span>
</code></pre></div></div><p>这将使用组件部分中定义的属性来初始化组件。许多组件都有属性，但这不是必需的。某些属性是必需的，而某些属性有默认值。如果您不确定组件支持哪些属性，请参阅开发者提供的文档，或使用编辑器管理面板中的检查器。当您在页面或布局组件面板中点击组件时，检查器将打开。</p><div class="custom-block aside"><p>如果两个同名组件同时分配给页面和布局，则页面组件将优先。</p></div><p>当您引用一个组件时，它会自动创建一个与组件名称匹配的页面变量（在前面的示例中为 <code>demoTodo</code>）。提供 HTML 标记的组件可以使用 <code>{% component %}</code> 标签在页面上渲染，如下所示。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block warning"><p>在部件中使用组件的功能有限，这在文档的<a href="./partials.html">动态部件部分</a>中有更详细的描述。</p></div><h2 id="组件别名"><a href="#组件别名" class="header-anchor">#</a> 组件别名</h2><p>如果有两个插件注册了同名的组件，您可以使用其完全限定类名来附加组件，并为其分配一个<em>别名</em>。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>部分中的第一个参数是类名，第二个是组件别名，将在附加到页面时使用。如果您指定了组件别名，则在页面代码中引用该组件时应处处使用它。请注意，下面的示例引用了组件别名：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>别名还允许您使用短名称在前、别名在后的方式，在同一页面上定义同一类的多个组件。这使您可以在一个页面上使用同一组件的多个实例。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><h2 id="使用外部属性值"><a href="#使用外部属性值" class="header-anchor">#</a> 使用外部属性值</h2><p>默认情况下，属性值在定义组件的配置部分中初始化，属性值是静态的，如下所示：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,20)),a[2]||(a[2]=n("div",null,[n("p",null,[s("但是，有一种方法可以使用从外部参数加载的值来初始化属性——URL 参数或"),n("a",{href:"./partials.html"},"部件"),s("参数（对于在部件中定义的组件）。使用 "),n("code",{"v-pre":""},"{{ paramName }}"),s(" 语法表示应从部件变量加载的值：")])],-1)),a[3]||(a[3]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>假设在上面的示例中组件 <strong>demoTodo</strong> 定义在一个部件中，它将使用从 <strong>maxItems</strong> 部件变量加载的值进行初始化：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-todo-partial<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>10<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>您可以使用点表示法从外部参数中获取深层嵌套的值：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ data.maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,5)),a[4]||(a[4]=n("div",null,[n("p",null,[s("要从 URL 参数加载属性值，请使用 "),n("code",{"v-pre":""},"{{ :paramName }}"),s(" 语法，其中名称以冒号（"),n("code",{"v-pre":""},":"),s("）开头，例如。")])],-1)),a[5]||(a[5]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ :maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>组件所属的页面应定义相应的 <a href="./pages.html">URL 参数</a>。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>在 October 后端中，您可以使用检查器工具将外部值分配给组件属性。在检查器中，您不需要使用花括号来输入参数名称。检查器中的每个字段右侧都有一个图标，用于打开外部参数名称编辑器。对于部件变量，输入参数名称为 <code>paramName</code>，对于 URL 参数，输入 <code>:paramName</code>。</p><h2 id="向组件传递变量"><a href="#向组件传递变量" class="header-anchor">#</a> 向组件传递变量</h2><p>组件可以设计为在渲染时使用变量，类似于<a href="./partials.html">部件变量</a>，可以在 <code>{% component %}</code> 标签中的组件名称后面指定。指定的变量将显式覆盖<a href="./../../extend/cms-components.html">组件属性</a>的值，包括外部属性值。</p><p>在此示例中，组件的 <strong>maxItems</strong> 属性将在渲染时设置为 <em>7</em>：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="自定义默认标记"><a href="#自定义默认标记" class="header-anchor">#</a> 自定义默认标记</h2><div class="custom-block aside"><p>组件中的默认标记是样板代码，旨在提供一个简单的使用示例。</p></div><p>有两种方法可以自定义组件的默认标记：</p><ul><li>将默认标记复制到您的主题中</li><li>逐个覆盖组件部件</li></ul><p>覆盖组件部件的用途非常有限。在大多数情况下，将组件的部件转换为 CMS 部件要容易得多，而且这样做几乎没有区别。</p><p>以一个像这样渲染的博客组件为例。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>上面的代码实际上等同于这样做。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog::default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>如果您将组件中的 <strong>default.htm</strong> 部件复制到主题中作为 <strong>blog-default.htm</strong> 部件，您可以用相同的方式渲染它。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>在这里我们可以看到使用 CMS 部件来自定义内容是很简单的，这展示了组件的真正强大之处。只有在极少数情况下主题才需要覆盖组件部件，下面将更详细地介绍这一点。</p><h3 id="将默认标记移动到部件"><a href="#将默认标记移动到部件" class="header-anchor">#</a> 将默认标记移动到部件</h3><p>每个组件都有一个名为 <strong>default.htm</strong> 的入口点部件，当调用 <code>{% component %}</code> 标签时会渲染它，在下面的示例中我们假设组件名为 <strong>blogPost</strong>。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blog/post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPost<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>输出将从插件目录 <strong>components/blogpost/default.htm</strong> 渲染。您可以将此文件中的所有标记复制并直接粘贴到页面中，或粘贴到一个新的部件中，例如名为 <strong>blog-post.htm</strong>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在标记中，您可能会注意到引用了一个名为 <code>__SELF__</code> 的变量，它指的是组件对象，应该替换为页面上使用的组件别名，在此示例中为 <code>blogPost</code>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>这是让默认组件标记在主题中任何位置工作所需的唯一更改。现在可以使用主题部件来自定义和渲染组件标记。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>此过程可以对组件部件目录中找到的所有其他部件重复执行。</p><h3 id="覆盖组件部件"><a href="#覆盖组件部件" class="header-anchor">#</a> 覆盖组件部件</h3><p>所有组件部件都可以使用主题部件来覆盖。当组件具有严格的实现时，这很有用，它提供了一种配置其标记的特定区域的选项。</p><p>例如，如果一个名为 <strong>channel</strong> 的组件使用了 <strong>title.htm</strong> 部件。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">mypage</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>channel<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>我们可以通过在主题中创建一个名为 <strong>partials/channel/title.htm</strong> 的文件来覆盖该部件。</p><p>文件路径段的分解如下：</p><div class="table"><table tabindex="0"><thead><tr><th>段</th><th>描述</th></tr></thead><tbody><tr><td><strong>partials</strong></td><td>主题部件目录</td></tr><tr><td><strong>channel</strong></td><td>组件别名（部件子目录）</td></tr><tr><td><strong>title.htm</strong></td><td>要覆盖的组件部件</td></tr></tbody></table></div><p>可以通过简单地为组件分配同名的别名来自定义部件子目录名称。例如，将 <strong>channel</strong> 组件分配一个不同的别名 <strong>foobar</strong>，覆盖目录也会随之更改。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel foobar</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>foobar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>现在我们可以通过在主题中创建名为 <strong>partials/foobar/title.htm</strong> 的文件来覆盖 <strong>title.htm</strong> 部件。</p><h2 id="view-bag-组件"><a href="#view-bag-组件" class="header-anchor">#</a> &quot;View Bag&quot; 组件</h2><div class="custom-block aside"><p>viewBag 组件在后端面板中是隐藏的，仅可用于基于文件的编辑。它也可以被其他插件用来存储数据。</p></div><p>October CMS 中包含一个名为 <code>viewBag</code> 的特殊组件，可以在任何页面或布局上使用。它允许定义临时属性，并在标记区域中作为变量轻松访问。一个很好的用法示例是在页面中定义活动菜单项。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">About</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/about.html</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">viewBag</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">activeMenu</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">about</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Page content...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>为组件定义的任何属性随后都可以在页面、布局或部件标记中使用 <code>viewBag</code> 变量来访问。例如，在此布局中，如果 <code>viewBag.activeMenu</code> 值设置为 <strong>about</strong>，则 <strong>active</strong> 类将被添加到列表项。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Default layout</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>...

<span class="token comment">&lt;!-- Main navigation --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> viewBag<span class="token punctuation">.</span>activeMenu <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>about<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>About<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h3 id="ajax-处理器和部件"><a href="#ajax-处理器和部件" class="header-anchor">#</a> AJAX 处理器和部件</h3><p>组件可以通过使用组件名称前缀和两个 <code>::</code> 符号，向主题的生命周期引入 <a href="./../ajax/introduction.html">AJAX 处理器</a>和<a href="./partials.html">部件</a>。例如，组件定义的所有 AJAX 处理器都是全局可用的。</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;onMyComponentHandler&quot;
</code></pre></div><p>但是，如果存在命名冲突，可以使用完全限定名称。</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;componentName::onMyComponentHandler&quot;
</code></pre></div><p>从组件外部渲染的部件必须使用其完全限定名称。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>componentName::component-partial<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>阅读更多关于<a href="./../../extend/cms-components.html">组件开发</a>的内容，以了解组件部件。</p><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../extend/cms-components.html">CMS 组件开发</a></li></ul></div>`,56))])}const b=c(r,[["render",g]]);export{x as __pageData,b as default};
